(() => {
  const visor = document.querySelector('.scanner');
  if (!visor || matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const visitKey = 'editclub.intro.v2';
  try { if (sessionStorage.getItem(visitKey)) return; } catch {}
  const video = visor.querySelector('video');
  const mobileIntro = matchMedia('(max-width:760px)').matches;
  visor.classList.toggle('mobile-intro', mobileIntro);
  const canvas = visor.querySelector('canvas');
  const pen = canvas.getContext('2d');
  const layer = video.parentElement;
  const lock = visor.querySelector('[data-lock]');
  const percent = visor.querySelector('[data-percent]');
  const tau = 2 * Math.PI;
  const anchors = [[0,.50,.49],[2.3,.53,.49],[2.68,.34,.36],[3.30,.29,.36],[3.72,.38,.49],[4.10,.42,.49],[4.30,.48,.49]];
  let width, height, field, frame, closed = false;
  const gestures = new AbortController();
  let audio, soundtrack, soundSource, nextPing = .2;
  const soundData = mobileIntro ? 'data:audio/mp4;base64,' : 'data:audio/mp4;base64,';
  function startSoundtrack() {
    if (closed || soundSource || !soundtrack || audio?.state !== 'running' || video.paused) return;
    const offset = video.currentTime;
    if (offset >= soundtrack.duration) return;
    soundSource = audio.createBufferSource();
    soundSource.buffer = soundtrack;
    soundSource.connect(audio.destination);
    soundSource.start(0, offset);
  }

  function alertTone(t) {
    if (!audio || audio.state !== 'running' || video.paused || t < nextPing || t >= 4.28) return;
    const threat = (t / 4.3) ** 1.5;
    nextPing = t + .58 - .46 * threat;
    const tone = audio.createOscillator();
    const gain = audio.createGain();
    const now = audio.currentTime;
    tone.frequency.value = 580 + 520 * threat;
    gain.gain.setValueAtTime(.0001,now);
    gain.gain.exponentialRampToValueAtTime(.045 + .055 * threat,now+.006);
    gain.gain.exponentialRampToValueAtTime(.0001,now+.076);
    tone.connect(gain).connect(audio.destination);
    tone.start(now);
    tone.stop(now+.08);
    tone.onended = () => {tone.disconnect();gain.disconnect();};
  }

  let goalX=0, goalY=0, yaw=0, pitch=0, lastTime;
  let projection=[1,0,0,1,0,0,0,0,1];
  function aim(event) {
    if(event.pointerType!=='mouse') return;
    goalX=(2*event.clientX/width-1)*.068;
    goalY=(2*event.clientY/height-1)*.041;
  }
  function center() {goalX=0; goalY=0;}
  function camera(now) {
    const blend=1-Math.exp(-Math.min(80,now-(lastTime??now))/64);
    lastTime=now;
    yaw+=(goalX-yaw)*blend;
    pitch+=(goalY-pitch)*blend;
    const cy=Math.cos(yaw), sy=Math.sin(yaw), cp=Math.cos(pitch), sp=Math.sin(pitch);
    const focal=Math.min(field.width,field.height)*.95;
    const zoom=1+Math.min(1,Math.abs(yaw)/.068+Math.abs(pitch)/.041)*.15;
    const a=zoom*cy, b=-zoom*sp*sy, d=zoom*cp;
    const tx=-zoom*sy*focal, ty=-zoom*sp*cy*focal;
    const g=cp*sy/focal, h=sp/focal, k=cp*cy;
    projection=[a,b,0,d,tx,ty,g,h,k];
    video.style.transform='matrix3d('+[a,b,0,g,0,d,0,h,0,0,1,0,tx,ty,0,k].join(',')+')';
  }
  function resize() {
    width = visor.clientWidth;
    height = visor.clientHeight;
    const scale = Math.min(devicePixelRatio,1.5);
    canvas.width = Math.round(width*scale);
    canvas.height = Math.round(height*scale);
    if (pen) pen.setTransform(scale,0,0,scale,0,0);
    field = layer.getBoundingClientRect();
  }
  function line(x,y,u,v) {
    pen.beginPath(); pen.moveTo(x,y); pen.lineTo(u,v); pen.stroke();
  }
  function arc(x,y,r,a,b) {
    pen.beginPath(); pen.arc(x,y,r,a,b); pen.stroke();
  }
  function optics(t,p,color) {
    pen.clearRect(0,0,width,height);
    if(t>4.31) return;
    const next = anchors.findIndex(key => key[0]>t);
    const a = anchors[next<0?anchors.length-1:Math.max(0,next-1)];
    const b = next<0?a:anchors[next];
    const f = Math.min(1,(t-a[0])/(b[0]-a[0] || 1));
    const smooth = f*f*(3-2*f);
    const u=field.width*(a[1]+(b[1]-a[1])*smooth-.5);
    const v=field.height*(a[2]+(b[2]-a[2])*smooth-.5);
    const [xx,yx,xy,yy,tx,ty,g,h,k]=projection;
    const depth=g*u+h*v+k;
    const x=field.left+field.width/2+(xx*u+xy*v+tx)/depth;
    const y=field.top+field.height/2+(yx*u+yy*v+ty)/depth;
    const r = Math.min(width*.19,height*.18)*(1.16-.31*p+.055*Math.cos(t*4));
    const pulse = (t*1.15+t*t*.22)%1;
    pen.strokeStyle=color;
    pen.lineWidth=1;
    pen.globalAlpha=.26*(1-pulse);
    arc(x,y,r*(1+pulse*.46),0,tau);
    pen.globalAlpha=.52;
    for(let i=0;i<60;i++){
      const angle=tau*i/60;
      const major=i%5===0;
      const end=r+(major?7:2.5);
      line(x+r*Math.cos(angle),y+r*Math.sin(angle),x+end*Math.cos(angle),y+end*Math.sin(angle));
    }
    pen.globalAlpha=.90;
    pen.lineWidth=2;
    for(let i=0;i<4;i++){
      const angle=tau*i/4+t*.33;
      arc(x,y,r*.91,angle,angle+.49);
    }
    pen.lineWidth=1;
    pen.globalAlpha=.65;
    const sweep=t*2.6 + .33*t*t;
    arc(x,y,r*.76,sweep-.8,sweep);
    line(x-4,y,x+4,y); line(x,y-4,x,y+4);
    const inset=Math.max(20,width*.045);
    const mid=height*.49;
    for(const side of [-1,1]){
      const edge=side<0?inset:width-inset;
      for(let i=-5;i<=5;i++){
        const offset=(i+(t*1.7)%1)*Math.min(height*.028,22);
        pen.globalAlpha=.46*(1-Math.abs(i)/6);
        line(edge,mid+offset,edge-side*(i%3===0?17:7),mid+offset);
      }
      pen.globalAlpha=.85;
      line(edge,mid,edge-side*23,mid);
    }
    pen.globalAlpha=1;
  }
  function draw() {
    if(closed) return;
    camera(performance.now());
    const t=video.currentTime;
    const p=Number.isFinite(video.duration)?Math.min(1,t/video.duration):0;
    const color=t<2.55?'#79e9ff':t<3.65?'#ffc36b':'#ff8069';
    alertTone(t);
    if(pen) optics(t,p,color);
    visor.style.setProperty('--signal',color);
    visor.style.setProperty('--level',Math.min(100,3+100*(t/4.3)**1.65)+'%');
    const status=t>4.31?'Sinal perdido':t>3.65?'Impacto iminente':t>2.55?'Ameaça próxima':t>.45?'Alvo detectado':'Buscando sinal';
    if(lock.textContent!==status) lock.textContent=status;
    const progressText=String(Math.floor(100*p));
    if(percent.textContent!==progressText) percent.textContent=progressText;
    frame=requestAnimationFrame(draw);
  }
  function close() {
    if(closed) return;
    closed=true;
    if (video.ended) { try {sessionStorage.setItem(visitKey,'seen');} catch {} }
    cancelAnimationFrame(frame);
    removeEventListener('resize',resize);
    visor.removeEventListener('pointermove',aim);
    visor.removeEventListener('pointerleave',center);
    gestures.abort();
    if(!video.ended) video.pause();
    if(soundSource) soundSource.stop();
    if(audio) audio.close().catch(()=>{});
    visor.close();
  }
  function unlock(event) {
    if (!event.isTrusted || closed || event.target?.closest?.('[data-skip]')) return;
    if (navigator.userActivation && !navigator.userActivation.isActive) return;
    if (audio?.state === 'suspended') audio.resume().then(startSoundtrack).catch(()=>{});
    else startSoundtrack();
  }
  visor.showModal();
  resize();
  addEventListener('resize',resize);
  visor.querySelector('[data-skip]').onclick=close;
  visor.addEventListener('cancel',event=>{event.preventDefault();close();});
  video.addEventListener('error',close);
  video.addEventListener('ended',()=>{percent.textContent='100';close();});
  visor.addEventListener('pointermove',aim,{passive:true});
  visor.addEventListener('pointerleave',center);
  for (const type of ['pointerdown','touchend','click','keydown']) {
    window.addEventListener(type,unlock,{capture:true,passive:true,signal:gestures.signal});
  }
  if (window.AudioContext) {
    try {
      audio = new AudioContext();
      fetch(soundData).then(response => response.arrayBuffer())
        .then(bytes => audio.decodeAudioData(bytes))
        .then(buffer => {soundtrack = buffer; startSoundtrack();})
        .catch(()=>{});
      audio.resume().then(startSoundtrack).catch(()=>{});
    } catch {}
  }
  video.addEventListener('playing',startSoundtrack);
  video.style.pointerEvents='none';
  video.src=mobileIntro ? 'motions-editor/editor-carregamento-mobile.mp4' : video.dataset.src;
  video.muted=true;
  video.play().catch(close);
  draw();
})();
